sys_transform_entry.source_script:
answer = (function transformEntry(source) {
    const timeStamp = new Date().toISOString(); //performance.timeOrigin + performance.now();
    const infoStr = 'OHS - ' + timeStamp + ' - Row: ' + source.sys_import_row +
        ' - Create Mitigation Actions - Get Parent Hazard - ';

    try {
        const posCode = source.u_position_code.toString(); //toString otherwise it's an object (which could be empty)
        const actionTaken = source.u_action_s__taken_by_manager.toString().trim();

        if (posCode !== null && posCode !== '' &&
            actionTaken !== null && actionTaken !== '') {
            //gs.debug(infoStr + '\nPosCode Exists: ' + posCode + ' - so does action: ' + actionTaken);

            const grPosCode = new GlideRecord('x_hccc_base_org_position_code');
            const grPosRep = new GlideRecord('x_hccc_hoc_ohs_position_reports_to');
            const grHira = new GlideRecord('x_hccc_hoc_ohs_hira_case');
            const grHazard = new GlideRecord('x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment');

            grPosCode.get('code', posCode); //should only have 1
            grPosRep.get('position_code', grPosCode.getUniqueValue()); //position reports to
            grHira.get('position_reporting_position', grPosRep.getUniqueValue()); //matching hira

            //Finding the hazard
            grHazard.addQuery('hira_case', grHira.getUniqueValue());
            grHazard.addQuery('work_task_description', source.u_work_task___description.toString());
            grHazard.addQuery('recommended_action', source.u_recommended__ller_crichton_.toString());
            grHazard.addQuery('controls_present', source.u_controls_present.toString());
            grHazard.addQuery('hazard_description', source.u_hazard_description.toString());
            grHazard.addQuery('regulatory_reference', source.u_regulatory_reference.toString());

            grHazard.query();

            if (grHazard.next()) {
                /*gs.debug(infoStr + '\nposCode: ' + posCode +
                    ' - posCodeId: ' + grPosCode.getUniqueValue() +
                    '\nPosRepId: ' + grPosRep.getUniqueValue() +
                    '\nHiraCaseId: ' + grHira.getUniqueValue() +
                    '\nHazardId: ' + grHazard.getUniqueValue() +
                    '\n\nSource: ' +
                    '\n|___work_task_description: ' + source.u_work_task___description.toString() +
                    '\n|___recommended_action: ' + source.u_recommended__ller_crichton_.toString() +
                    '\n|___controls_present: ' + source.u_controls_present.toString() +
                    '\n|___hazard_description: ' + source.u_hazard_description.toString() +
                    '\n|___regulatory_reference: ' + source.u_regulatory_reference.toString()
                );*/

                return grHazard.getUniqueValue();
            } else {
                //gs.warn(infoStr + 'Could not find parent hazard. Source: ' + JSON.stringify(source));
                log.warn(infoStr + 'Could not find parent hazard.');
            }
        }
    } catch (e) {
        //gs.error(infoStr + 'ERROR: ' + e);
        //gs.error(infoStr + 'ERROR - source content: ' + JSON.stringify(source));
        log.error(infoStr + 'ERROR: ' + e);
    }

    //No Return since if there's no posCode we reject (returning NULL or undefined seems to be considered like there is a value)
    //return null;
})(source);
